sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float strength;
uniform float2 offset;
uniform float count;
uniform float2 stretch;
uniform float angle;
uniform float seed;
float hash12(float2 p) {
    float3 q = fract(float3(p.xyx) * 0.1031);
    q += dot(q, q.yzx + 33.33);
    return fract((q.x + q.y) * q.z);
}
float2 hash22(float2 p) {
    float3 q = fract(float3(p.xyx) * float3(0.1031, 0.1030, 0.0973));
    q += dot(q, q.yzx + 33.33);
    return fract((q.xx + q.yz) * q.zy);
}
half4 main(float2 coord) {
    float cell = size.y / (2.475 * max(count, 0.5));
    float a = radians(angle);
    float cs = cos(a);
    float sn = sin(a);
    float2 c = size * 0.5 + offset;
    float2 p = coord - c;
    p = float2(cs * p.x + sn * p.y, -sn * p.x + cs * p.y);
    float2 dims = max(abs(stretch), float2(0.01)) * cell;
    float2 g = p / dims;
    float2 n = floor(g);
    float2 h = hash22(n + seed * 13.17);
    float t = h.x * 6.2831853;
    float2 d = float2(cos(t), sin(t)) * h.y * strength * min(size.x, size.y);
    float2 inside = step(float2(0.0), coord) * step(coord, size);
    return image.eval(coord + d) * half(inside.x * inside.y);
}
